#!/usr/bin/env node
// Differential fuzzer for the numeric core.
// Usage: node fuzz_num_agent1.mjs <casefile> <cwd> [concurrency]
// casefile: one line per case, six whitespace-separated ints (a b c d e f)
import { spawn } from 'node:child_process';
import { readFileSync } from 'node:fs';

const REF = '/workspace/dataset/test20_executable';
const NEW = '/output/test20.mjs';

const [, , caseFile, cwd, concArg] = process.argv;
const CONC = Number(concArg || 32);

const cases = readFileSync(caseFile, 'utf8')
  .split('\n')
  .map((l) => l.trim())
  .filter(Boolean)
  .map((l) => l.split(/\s+/));

function run(cmd, args, cwd) {
  return new Promise((resolve) => {
    const p = spawn(cmd, args, { cwd, stdio: ['ignore', 'pipe', 'pipe'] });
    const out = [], err = [];
    p.stdout.on('data', (d) => out.push(d));
    p.stderr.on('data', (d) => err.push(d));
    p.on('close', (code, sig) => {
      resolve({
        code: code === null ? 128 + 1 : code,
        out: Buffer.concat(out).toString('binary'),
        err: Buffer.concat(err).toString('binary'),
      });
    });
  });
}

const stripPyi = (s) =>
  s.split('\n').filter((l) => !/^\[PYI-\d+:ERROR\]/.test(l)).join('\n');

let diffs = 0, total = 0;

async function worker(iter) {
  for (const tup of iter) {
    const argv = ['--a', tup[0], '--b', tup[1], '--c', tup[2], '--d', tup[3], '--e', tup[4], '--f', tup[5]];
    const [r, n] = await Promise.all([run(REF, argv, cwd), run(process.execPath, [NEW, ...argv], cwd)]);
    total++;
    const rerr = stripPyi(r.err);
    if (r.code !== n.code || r.out !== n.out || rerr !== n.err) {
      diffs++;
      console.log(`DIFF ${argv.join(' ')}  [cwd=${cwd}]`);
      console.log(`  rc ref=${r.code} new=${n.code}`);
      if (r.out !== n.out) {
        console.log(`  REF.out=${JSON.stringify(r.out)}`);
        console.log(`  NEW.out=${JSON.stringify(n.out)}`);
      }
      if (rerr !== n.err) {
        console.log(`  REF.err=${JSON.stringify(rerr)}`);
        console.log(`  NEW.err=${JSON.stringify(n.err)}`);
      }
    }
  }
}

const it = cases[Symbol.iterator]();
await Promise.all(Array.from({ length: CONC }, () => worker(it)));
console.log(`TOTAL=${total} DIFFS=${diffs} cwd=${cwd}`);

#!/usr/bin/env node
// Case generator for the numeric fuzz. Prints six ints per line.
import { writeFileSync } from 'node:fs';

// deterministic PRNG (mulberry32)
function mk(seed) {
  return function () {
    seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rnd = mk(Number(process.argv[3] || 12345));
const pick = (a) => a[Math.floor(rnd() * a.length)];
const ri = (lo, hi) => lo + Math.floor(rnd() * (hi - lo + 1));

const lines = [];
const seen = new Set();
const add = (t) => {
  const k = t.join(' ');
  if (!seen.has(k)) { seen.add(k); lines.push(k); }
};

// ---------- 1. explicit structured cases ----------
// zeros in every single position
for (let pos = 0; pos < 6; pos++) {
  for (let rep = 0; rep < 12; rep++) {
    const t = [ri(-30, 30) || 7, ri(-30, 30) || 5, ri(-30, 30) || 3, ri(-30, 30) || 11, ri(-30, 30) || 2, ri(-30, 30) || 9];
    t[pos] = 0;
    add(t);
  }
}
// zeros in every pair / triple / etc of positions (all 63 non-empty subsets, several reps)
for (let mask = 1; mask < 64; mask++) {
  for (let rep = 0; rep < 4; rep++) {
    const t = [ri(-20, 20) || 7, ri(-20, 20) || 5, ri(-20, 20) || 3, ri(-20, 20) || 11, ri(-20, 20) || 2, ri(-20, 20) || 9];
    for (let i = 0; i < 6; i++) if (mask & (1 << i)) t[i] = 0;
    add(t);
  }
}
// all combinations of {-1,0,1} in a,c,e with small denominators
for (const a of [-1, 0, 1]) for (const c of [-1, 0, 1]) for (const e of [-1, 0, 1])
  for (const b of [-1, 1, 2, -3]) for (const d of [1, -2, 3]) for (const f of [-1, 1, 4])
    add([a, b, c, d, e, f]);

// all-small exhaustive-ish: values from {-2..2} \ {} in all six slots (sampled)
const small = [-2, -1, 0, 1, 2];
for (let i = 0; i < 500; i++) add([pick(small), pick(small), pick(small), pick(small), pick(small), pick(small)]);

// equal fractions (comparisons false both ways) - scaled duplicates
for (let i = 0; i < 120; i++) {
  const n = ri(-15, 15), d = ri(-15, 15) || 1;
  const k1 = ri(1, 12), k2 = ri(1, 12), k3 = ri(1, 12);
  const s1 = pick([1, -1]), s2 = pick([1, -1]), s3 = pick([1, -1]);
  add([n * k1 * s1, d * k1 * s1, n * k2 * s2, d * k2 * s2, n * k3 * s3, d * k3 * s3]);
}
// two equal, third different
for (let i = 0; i < 80; i++) {
  const n = ri(-12, 12), d = ri(-12, 12) || 1, k = ri(2, 9);
  add([n, d, n * k, d * k, ri(-12, 12), ri(-12, 12) || 1]);
  add([ri(-12, 12), ri(-12, 12) || 1, n, d, n * k, d * k]);
}

// large common factors: multiples of 360, powers of 2, primorials
const factors = [360, 720, 1080, 2, 4, 8, 16, 32, 64, 128, 256, 512, 1024, 2310, 30030, 510510, 6, 30, 210, 2310];
for (let i = 0; i < 260; i++) {
  const g = pick(factors);
  const s = () => pick([1, 1, 1, -1]);
  add([g * ri(1, 9) * s(), g * ri(1, 9) * s(), g * ri(1, 9) * s(), g * ri(1, 9) * s(), g * ri(1, 9) * s(), g * ri(1, 9) * s()]);
}
// mixed: some limbs share factor with others
for (let i = 0; i < 120; i++) {
  const g1 = pick(factors), g2 = pick(factors);
  add([g1 * ri(-6, 6), g2 * (ri(1, 6)), g2 * ri(-6, 6), g1 * ri(1, 6), g1 * g2 * pick([1, -1]), g1 * ri(1, 6)]);
}

// equal numerators / equal denominators
for (let i = 0; i < 100; i++) {
  const n = ri(-40, 40), d = ri(-40, 40) || 1;
  add([n, ri(-20, 20) || 1, n, ri(-20, 20) || 1, n, ri(-20, 20) || 1]);
  add([ri(-20, 20), d, ri(-20, 20), d, ri(-20, 20), d]);
}

// negative denominators only (sign normalisation)
for (let i = 0; i < 150; i++) add([ri(-50, 50), -Math.abs(ri(1, 50)), ri(-50, 50), -Math.abs(ri(1, 50)), ri(-50, 50), -Math.abs(ri(1, 50))]);
// all positive
for (let i = 0; i < 200; i++) add([ri(1, 99), ri(1, 99), ri(1, 99), ri(1, 99), ri(1, 99), ri(1, 99)]);
// all negative
for (let i = 0; i < 200; i++) add([-ri(1, 99), -ri(1, 99), -ri(1, 99), -ri(1, 99), -ri(1, 99), -ri(1, 99)]);
// mixed signs random small
for (let i = 0; i < 400; i++) add([ri(-99, 99), ri(-99, 99) || 1, ri(-99, 99), ri(-99, 99) || 1, ri(-99, 99), ri(-99, 99) || 1]);
// ones and minus ones heavy
const ones = [-1, 1, -1, 1, 2, -2, 3, 0];
for (let i = 0; i < 200; i++) add([pick(ones), pick(ones), pick(ones), pick(ones), pick(ones), pick(ones)]);

// harmonic-mean cancellation: 1/f1+1/f2+1/f3 == 0
for (let i = 0; i < 60; i++) {
  // f1 = p/q, f2 = -p/q  => 1/f1 + 1/f2 = 0, then need 1/f3 = 0 impossible;
  // instead force sum of reciprocals zero: b/a + d/c + f/e = 0
  const a = ri(1, 20), b = ri(1, 20), c = ri(1, 20), d = ri(1, 20);
  // want f/e = -(b/a + d/c) = -(b*c + d*a)/(a*c)
  const num = -(b * c + d * a), den = a * c;
  add([den, num, a, b, c, d].slice(0, 6));
  add([a, b, c, d, den, num]);
}

// digit-boundary / carry stress within small range
const bnd = [9999999, 10000000, 10000001, 99999999, 100000000, 1, -1, 9999998, -10000000];
for (let i = 0; i < 120; i++) add([pick(bnd), pick(bnd), pick(bnd), pick(bnd), pick(bnd), pick(bnd)]);

// leading-zero / plus-sign textual forms of small ints
// (handled separately)

writeFileSync(process.argv[2], lines.join('\n') + '\n');
console.error(`generated ${lines.length} cases`);

