#!/usr/bin/env node
// Batch 3: randomized argv orderings, '=' forms, repeated options, with random small ints.
import { spawn } from 'node:child_process';
const REF = '/workspace/dataset/test20_executable';
const NEW = '/output/test20.mjs';
const cwd = '/tmp/a1clean';
function mk(s){return function(){s|=0;s=(s+0x6D2B79F5)|0;let t=Math.imul(s^(s>>>15),1|s);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
const rnd = mk(90210);
const ri=(lo,hi)=>lo+Math.floor(rnd()*(hi-lo+1));
const pick=(a)=>a[Math.floor(rnd()*a.length)];
