const strip=s=>s.split('\n').filter(l=>!/^\[PYI-\d+:ERROR\]/.test(l)).join('\n');

const argvs=[];
const names=['a','b','c','d','e','f'];
for(let i=0;i<900;i++){
  const vals={a:ri(-40,40),b:ri(-40,40),c:ri(-40,40),d:ri(-40,40),e:ri(-40,40),f:ri(-40,40)};
  // occasionally force zeros
  if(rnd()<0.35) vals[pick(names)]=0;
  if(rnd()<0.15) vals[pick(names)]=0;
  if(rnd()<0.2) vals[pick(names)]=pick([1,-1]);
